package mpv1

// Wire parity for the durable-loop park fields (build plan WS03 S8-2). Add this file AFTER
// `buf generate` has produced the new fields (RunAgentResponse.ParkReason, the
// OrchestrationEvent RunParked and RunResumed variants, SaveLoopCheckpointResponse.ParkAccepted).
// The same bytes are pinned in:
//   rust/crates/mp-contracts/tests/proto_wire_parity_execution.rs  (PARKED_WIRE_HEX, the save response)
//   rust/crates/mp-orchestration/src/proto_shim.rs                 (run_parked_and_run_resumed_encode_to_the_golden_bytes)

import (
	"encoding/hex"
	"testing"

	"google.golang.org/protobuf/proto"
)

const (
	// status "parked", rounds 2, resets_at (field 8) and park_reason (field 11).
	parkedWireHex = "0a067061726b656418024214323032362d30392d32365430313a32313a30305a5a1270726f76696465725f657868617573746564"
	// Envelope at = 1_700_000_000 s, then field 24 RunParked{run_id = \"run-1\"}.
	goldenOrchRunParkedHex = "0a060880e2cfaa06c201070a0572756e2d31"
	// Envelope at = 1_700_000_000 s, then field 25 RunResumed{run_id = \"run-1\", resumed_segment = 3}.
	goldenOrchRunResumedHex = "0a060880e2cfaa06ca01090a0572756e2d311003"
	// seq 7 (field 1) and park_accepted true (field 2).
	saveParkAcceptedWireHex = "08071001"
)

func unhexOrFatal(t *testing.T, h string) []byte {
	t.Helper()
	raw, err := hex.DecodeString(h)
	if err != nil {
		t.Fatalf("bad golden hex: %v", err)
	}
	return raw
}

func TestRunAgentResponseParkReasonIsField11(t *testing.T) {
	var decoded RunAgentResponse
	if err := proto.Unmarshal(unhexOrFatal(t, parkedWireHex), &decoded); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if decoded.GetStatus() != "parked" || decoded.GetRoundsExecuted() != 2 {
		t.Fatalf("status/rounds = %q/%d", decoded.GetStatus(), decoded.GetRoundsExecuted())
	}
	if decoded.GetParkReason() != "provider_exhausted" || decoded.GetResetsAt() != "2026-09-26T01:21:00Z" {
		t.Fatalf("park_reason/resets_at = %q/%q", decoded.GetParkReason(), decoded.GetResetsAt())
	}
	if decoded.GetFailureCode() != "" || decoded.GetFinalOutput() != "" {
		t.Fatalf("a park carries no failure code and no final output")
	}
}

func TestOrchestrationEventRunParkedAndRunResumedAreTags24And25(t *testing.T) {
	parked := decodeOrchHex(t, goldenOrchRunParkedHex)
	p, ok := parked.GetEvent().(*OrchestrationEvent_RunParked_)
	if !ok {
		t.Fatalf("variant = %T, want *OrchestrationEvent_RunParked_", parked.GetEvent())
	}
	if p.RunParked.GetRunId() != "run-1" {
		t.Fatalf("run_id = %q", p.RunParked.GetRunId())
	}
	resumed := decodeOrchHex(t, goldenOrchRunResumedHex)
	r, ok := resumed.GetEvent().(*OrchestrationEvent_RunResumed_)
	if !ok {
		t.Fatalf("variant = %T, want *OrchestrationEvent_RunResumed_", resumed.GetEvent())
	}
	if r.RunResumed.GetRunId() != "run-1" || r.RunResumed.GetResumedSegment() != 3 {
		t.Fatalf("run_id/resumed_segment = %q/%d", r.RunResumed.GetRunId(), r.RunResumed.GetResumedSegment())
	}
}

func TestSaveLoopCheckpointResponseParkAcceptedIsField2(t *testing.T) {
	var decoded SaveLoopCheckpointResponse
	if err := proto.Unmarshal(unhexOrFatal(t, saveParkAcceptedWireHex), &decoded); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if decoded.GetSeq() != 7 || !decoded.GetParkAccepted() {
		t.Fatalf("seq/park_accepted = %d/%v", decoded.GetSeq(), decoded.GetParkAccepted())
	}
	var oldStore SaveLoopCheckpointResponse
	if err := proto.Unmarshal(unhexOrFatal(t, "0807"), &oldStore); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if oldStore.GetParkAccepted() {
		t.Fatalf("a store that predates the field must read as not accepted")
	}
}

